### 5. **"Finished" Reading Logic** (LibraryView.swift, lines 431–465)

The **only** place "Finished" is marked:

```swift
@ViewBuilder
private var readingProgress: some View {
    if let raw = work.lastReadProgress, raw > 0 {
        let progress = min(max(raw, 0), 1)
        let finished = progress >= 0.99 || (work.isComplete && progress >= 0.95)  // ← THRESHOLD
        VStack(alignment: .leading, spacing: 3) {
            ProgressView(value: progress)
                .tint(finished ? .green : .accentColor)
                .scaleEffect(x: 1, y: 0.7, anchor: .center)
            HStack(spacing: 6) {
                if finished {
                    HStack(spacing: 4) {
                        Image(systemName: "checkmark.circle.fill")
                        Text("Finished")  // ← LABEL
                    }
                    .foregroundStyle(.green)
                } else {
                    Text("\(Int(progress * 100))% read")
                    if let chapter = work.lastReadChapter, (work.totalChapters ?? 0) > 1 {
                        Text("· Ch \(chapter)")
                    }
                }
                Spacer(minLength: 4)
                if let lastReadAt = work.lastReadAt {
                    Text(lastReadAt, format: .relative(presentation: .named))
                }
            }
            .font(.caption2)
            .foregroundStyle(.secondary)
            .lineLimit(1)
        }
        .padding(.top, 2)
        .accessibilityElement(children: .combine)
        .accessibilityLabel(finished ? "Finished reading" : "\(Int(progress * 100)) percent read")
    }
}
```

**Threshold for "Finished":**
- **`progress >= 0.99`** (99% or higher), OR
- **`work.isComplete && progress >= 0.95`** (95% for completed works)

No other "finished" concept exists in the reader or elsewhere; CLAUDE.md's reference to "% read / Finished" is this logic.

